    descriptionAdvanced: {
      de: "Der Taichung Metropolitan Park liegt auf dem Dadu-Bergplateau an der Grenze zwischen den Bezirken Xitun und Shalu und ist mit 88 Hektar die größte Grünanlage im Großraum Taichung. Er wurde im Jahr 2000 offiziell eröffnet und dient als wichtige ökologische Barriere sowie als Erholungsgebiet für die Stadtbewohner. Der Park ist so konzipiert, dass er die lokale Flora des Küstengebirges schützt und gleichzeitig Räume für Freizeitaktivitäten bietet. Die Architektur des Besucherzentrums und der Beobachtungsplattformen ist modern und bietet weite Ausblicke auf das Taichung-Becken im Osten und die Taiwanstraße im Westen. Die Anlage umfasst verschiedene Bereiche wie den Planetengarten, botanische Gärten und ein Amphitheater im Freien. Durch seine erhöhte Lage herrscht im Park oft eine kühle Brise, was ihn zu einem idealen Ort für die Beobachtung des Sonnenuntergangs und der nächtlichen Stadtlichter macht. Der Park spielt zudem eine wichtige Rolle im Wassermanagement der Region, indem er als natürliches Versickerungsgebiet dient. Mit seinen ausgedehnten Rad- und Wanderwegen fördert er einen gesunden Lebensstil in der Metropolregion.",
      hu: "A Taichung Városi Park a Dadu-hegy fennsíkján, Xitun és Shalu körzetek határán található; 88 hektáros területével ez a legnagyobb zöldfelület Taichung térségében. A parkot 2000-ben nyitották meg hivatalosan, és fontos ökológiai gátként, valamint a városlakók kiemelt pihenőhelyeként szolgál. A tervezés során elsődleges szempont volt a partmenti hegyvidék őshonos növényvilágának védelme és a szabadidős terek kialakítása. A látogatóközpont és a kilátóplatformok építészeti stílusa modern, lenyűgöző kilátást nyújtva kelet felé a Taichung-medencére, nyugat felé pedig a Tajvani-szorosra. A park különböző részekre oszlik, többek között megtalálható itt a bolygókert, botanikus kertek és egy szabadtéri amfiteátrum is. Megemelt helyzete miatt a parkban gyakran kellemes szellő fúj, így ideális helyszín a naplemente és a város éjszakai fényeinek megtekintéséhez. A park emellett fontos szerepet játszik a régió vízgazdálkodásában, természetes víznyelő területként működve. Kiterjedt kerékpár- és sétaútvonalai révén az egészséges életmódot népszerűsíti a nagyvárosi környezetben.",
      ro: "Parcul Metropolitan Taichung, situat pe platoul Muntelui Dadu la granița dintre districtele Xitun și Shalu, este cea mai mare zonă verde din zona metropolitană Taichung, având 88 de hectare. Inaugurat oficial în anul 2000, parcul servește ca o barieră ecologică vitală și ca zonă de recreere pentru locuitorii orașului. Proiectarea parcului a vizat protejarea florei native a munților de coastă, oferind în același timp spații generoase pentru activități în aer liber. Arhitectura centrului pentru vizitatori și a platformelor de observație este modernă, oferind vederi spectaculoase spre bazinul Taichung la est și spre strâmtoarea Taiwan la vest. Facilitățile includ diverse zone tematice, cum ar fi grădina planetelor, grădini botanice și un amfiteatru în aer liber. Datorită altitudinii sale, parcul beneficiază de o briză răcoroasă, fiind un loc ideal pentru a observa apusul și luminile orașului pe timp de noapte. Parcul joacă, de asemenea, un rol crucial în managementul apelor din regiune, acționând ca o zonă naturală de infiltrare. Cu pistele sale extinse de biciclete și traseele de mers pe jos, acesta promovează un stil de viață sănătos.",
      en: "Taichung Metropolitan Park, situated on the Dadu Mountain plateau on the border of Xitun and Shalu districts, is the largest green space in the Taichung metropolitan area, covering 88 hectares. Officially opened in 2000, it serves as a critical ecological barrier and a major recreational hub for urban residents. The park was designed to protect the native flora of the coastal mountains while providing ample space for leisure activities. The architecture of the visitor center and observation decks is modern, offering panoramic views of the Taichung Basin to the east and the Taiwan Strait to the west. The park features various thematic sections, including the Planet Garden, botanical gardens, and an open-air amphitheater. Due to its elevated position, the park often enjoys a cool breeze, making it an ideal spot for viewing sunsets and the city's night lights. Additionally, the park plays a vital role in regional water management by serving as a natural infiltration area. With its extensive network of cycling and walking trails, it promotes a healthy lifestyle within the metropolitan environment.",
      es: "El Parque Metropolitano de Taichung en Taichung, Taiwán, se inauguró en 1996 y abarca 80 hectáreas. Ofrece grandes céspedes, un lago y un pabellón. Alberga el Pabellón de Taichung, utilizado para exposiciones. El parque cuenta con un sendero de copas de árboles de 1,5 kilómetros. Unos 2 millones de personas lo visitan anualmente. La altitud es de 50 metros. En el parque se realizan conciertos y festivales. La temperatura media es de 23 °C.",
      pt: "O Parque Metropolitano de Taichung em Taichung, Taiwan, foi inaugurado em 1996 e abrange 80 hectares. Oferece grandes relvados, um lago e um pavilhão. Abriga o Pavilhão de Taichung, usado para exposições. O parque possui um trilho de copas de árvores de 1,5 quilómetros. Cerca de 2 milhões de pessoas visitam-no anualmente. A altitude é de 50 metros. No parque realizam-se concertos e festivais. A temperatura média é de 23 °C.",
      fr: "Le parc métropolitain de Taichung, à Taïwan, a été inauguré en 1996 et s'étend sur 80 hectares. Il offre de grandes pelouses, un lac et un pavillon. Il abrite le pavillon de Taichung, utilisé pour des expositions. Le parc dispose d'un sentier de la canopée de 1,5 kilomètre. Environ 2 millions de personnes le visitent chaque année. L'altitude est de 50 mètres. Le parc accueille des concerts et des festivals. La température moyenne est de 23 °C.",
    },
