      de: ["Der Park wurde am 28. Oktober 2000 offiziell eingeweiht.", "Er umfasst eine Gesamtfläche von 88 Hektar auf dem Dadu-Berg.", "Der Park ist in Zonen für Ökologie, Erholung und Bildung unterteilt.", "Es gibt eine große Sonnenuhr als zentrales Wahrzeichen im Park.", "Vom Park aus sind bei klarer Sicht Schiffe in der Taiwanstraße zu sehen.", "Die jährliche Besucherzahl übersteigt regelmäßig eine Million Menschen."],
      hu: ["A parkot hivatalosan 2000. október 28-án adták át.", "A Dadu-hegyen elterülő park teljes területe 88 hektár.", "A terület ökológiai, rekreációs és oktatási zónákra oszlik.", "A park egyik központi látványossága egy hatalmas napóra.", "Tiszta időben a Tajvani-szorosban haladó hajók is láthatók innen.", "Az éves látogatószám rendszeresen meghaladja az egymillió főt."],
      ro: ["Parcul a fost inaugurat oficial pe data de 28 octombrie 2000.", "Suprafața totală a parcului pe Muntele Dadu este de 88 de hectare.", "Este împărțit în zone dedicate ecologiei, recreerii și educației.", "O cadran solar de mari dimensiuni este reperul central al parcului.", "În zilele senine, navele din strâmtoarea Taiwan pot fi văzute de aici.", "Numărul anual de vizitatori depășește frecvent pragul de un milion."],
      en: ["The park was officially inaugurated on October 28, 2000.", "It covers a total land area of 88 hectares on Dadu Mountain.", "The park is divided into ecological, recreational, and educational zones.", "A large sundial serves as a prominent central landmark in the park.", "Ships in the Taiwan Strait can be seen from the park on clear days.", "The annual visitor count consistently exceeds one million people."],
      es: ["Superficie: 80 hectáreas", "Inauguración: 1996", "Altitud: 50 m", "Longitud sendero de copas: 1,5 km", "Visitantes anuales: 2 millones", "Lago: 3 hectáreas"],
      pt: ["Área: 80 hectares", "Inauguração: 1996", "Altitude: 50 m", "Comprimento do trilho de copas: 1,5 km", "Visitantes anuais: 2 milhões", "Lago: 3 hectares"],
